<script setup lang="ts">import{onMounted,ref,watch}from'vue';import{api}from'../api/client';const leases=ref<any[]>([]),leaseID=ref(''),items=ref<any[]>([]),balance=ref<any>(null),showModal=ref(false),form=ref({kind:'collect',reference:'',reason:'',amount:0});async function init(){leases.value=(await api.get('/leases',{params:{page:1,page_size:100}})).data.items||[];if(leases.value.length)leaseID.value=leases.value[0].ID}async function load(){if(!leaseID.value)return;const r=await api.get(`/leases/${leaseID.value}/deposits`);items.value=r.data.items||[];balance.value=r.data.balance}async function add(){await api.post(`/leases/${leaseID.value}/deposits`,form.value);showModal.value=false;await load()}watch(leaseID,load);onMounted(async()=>{await init();await load()})</script><template><div class="page"><div class="page-title"><div><h1>押金流水</h1><p>处理押金收取、扣款、补缴和退租返还</p></div><button class="primary-button" :disabled="!leaseID" @click="showModal=true">＋ 登记押金操作</button></div><section class="card"><div class="toolbar"><div><h3 style="margin:0">选择租约</h3><p style="margin:6px 0 0;color:#8b97a9;font-size:12px">押金余额按租约独立核算</p></div><div class="field"><select v-model="leaseID" style="min-width:360px"><option value="">请选择租约</option><option v-for="x in leases" :key="x.ID" :value="x.ID">{{x.PropertyID.slice(0,8)}} · {{String(x.StartDate).slice(0,10)}} 至 {{String(x.EndDate).slice(0,10)}}</option></select></div></div></section><div class="stat-grid"><div class="stat-card"><span>累计收取</span><strong>{{balance?.Received||0}}</strong></div><div class="stat-card"><span>累计扣款</span><strong>{{balance?.Deducted||0}}</strong></div><div class="stat-card"><span>累计返还</span><strong>{{balance?.Refunded||0}}</strong></div><div class="stat-card"><span>当前可用</span><strong>{{balance?(balance.Received-balance.Deducted-balance.Refunded):0}}</strong></div></div><section class="card"><table v-if="items.length" class="data-table"><thead><tr><th>时间</th><th>操作类型</th><th>金额</th><th>流水号</th><th>原因</th></tr></thead><tbody><tr v-for="x in items" :key="x.ID"><td>{{String(x.CreatedAt).replace('T',' ').slice(0,19)}}</td><td><span class="status-badge">{{({collect:'收取',topup:'补缴',deduct:'扣款',refund:'返还'} as any)[x.Kind]}}</span></td><td><strong>{{x.Amount}}</strong></td><td>{{x.Reference}}</td><td>{{x.Reason}}</td></tr></tbody></table><div v-else class="empty-state"><b>暂无押金流水</b><span>选择租约后登记第一笔押金收取</span></div></section><div v-if="showModal" class="modal-mask" @click.self="showModal=false"><div class="modal"><div class="modal-header"><h3>登记押金操作</h3><button class="close-button" @click="showModal=false">×</button></div><div class="modal-body"><div class="form-grid"><label><span>操作类型</span><select v-model="form.kind"><option value="collect">首次收取</option><option value="topup">押金补缴</option><option value="deduct">押金扣款</option><option value="refund">押金返还</option></select></label><label><span>金额 *</span><input v-model.number="form.amount" type="number" min="1"></label><label><span>唯一流水号 *</span><input v-model="form.reference" placeholder="例如 DEP-202608-001"></label><label><span>操作原因 *</span><input v-model="form.reason" placeholder="请输入原因"></label></div></div><div class="modal-footer"><button class="secondary-button" @click="showModal=false">取消</button><button class="primary-button" @click="add">确认登记</button></div></div></div></div></template>